using System;using System.Linq;using Verse;using Verse.AI;using PlayableRecreation;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;TogetherMatch.Reset();TogetherInvite.Reset();foreach(var q in ((Pawn[])Host.State["pair"]))q.jobs.EndCurrentJob(JobCondition.InterruptForced);int start=Find.TickManager.TicksGame;Action close=()=>{foreach(var w in Find.WindowStack.Windows.ToList())if(w.GetType().Name.Contains("Faction")||w.GetType().Name.Contains("EditWindow_Log"))w.Close(false);};close();Host.Watch=()=>{close();if(Find.TickManager.TicksGame-start>240){Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Settling load-time stale jobs and VEF faction dialog before retest.";}}
